import tkinter as tk
from tkinter import messagebox
import base64
import os
import tempfile

# ============================================================
# SCENTINEL AI - DIGITAL NOSE SIMULATION
# Single-file version: the four MP3 voice files are embedded.
#
# Voice order supplied:
# 1. Flower
# 2. Coffee
# 3. Spoiled Food
# 4. Smoke
#
# Install pygame once in the VS Code terminal:
#     python -m pip install pygame
#
# Then run:
#     python simulation.py
# ============================================================

AUDIO_DATA = {
    "Flower": """""",
    "Coffee": """""",
    "Spoiled Food": """""",
    "Smoke": """""",
}

try:
    import pygame
    pygame.mixer.init()
    PYGAME_OK = True
except Exception:
    PYGAME_OK = False


class ScentinelApp:
    def __init__(self, root):
        self.root = root
        self.root.title("SCENTINEL AI - Digital Nose")
        self.root.geometry("1000x650")
        self.root.minsize(850, 560)
        self.root.configure(bg="#08111f")

        self.temp_files = []
        self.odors = {
            "Flower": {
                "voc": "Low–moderate VOC",
                "mq2": "0.18",
                "mq135": "0.31",
                "temperature": "26.4 °C",
                "humidity": "58 %",
                "voice": "Flower-like odour detected."
            },
            "Coffee": {
                "voc": "Moderate VOC",
                "mq2": "0.27",
                "mq135": "0.46",
                "temperature": "27.1 °C",
                "humidity": "55 %",
                "voice": "Coffee-like odour detected."
            },
            "Spoiled Food": {
                "voc": "High VOC",
                "mq2": "0.63",
                "mq135": "0.78",
                "temperature": "28.2 °C",
                "humidity": "67 %",
                "voice": "Spoiled food odour detected."
            },
            "Smoke": {
                "voc": "Very high VOC",
                "mq2": "0.91",
                "mq135": "0.88",
                "temperature": "30.0 °C",
                "humidity": "49 %",
                "voice": "Smoke detected. Please take caution."
            }
        }

        self.build_header()
        self.show_home()

    def build_header(self):
        header = tk.Frame(self.root, bg="#0d1b2a", height=75)
        header.pack(fill="x")
        header.pack_propagate(False)

        tk.Label(
            header, text="SCENTINEL AI",
            font=("Segoe UI", 24, "bold"),
            fg="#55d6ff", bg="#0d1b2a"
        ).pack(side="left", padx=30)

        tk.Label(
            header, text="DIGITAL NOSE • ODOUR DETECTION SIMULATION",
            font=("Segoe UI", 10),
            fg="#9db3c8", bg="#0d1b2a"
        ).pack(side="left", padx=5)

    def clear_content(self):
        # Keep only the header; remove all other packed frames.
        for widget in self.root.pack_slaves():
            if widget != self.root.pack_slaves()[0]:
                widget.destroy()

    def content_frame(self):
        frame = tk.Frame(self.root, bg="#08111f")
        frame.pack(fill="both", expand=True, padx=35, pady=30)
        return frame

    def show_home(self):
        self.clear_content()
        frame = self.content_frame()

        tk.Label(
            frame, text="DIGITAL NOSE",
            font=("Segoe UI", 34, "bold"),
            fg="white", bg="#08111f"
        ).pack(pady=(35, 8))

        tk.Label(
            frame,
            text="Scentinel AI — Intelligent Odour Detection & Voice Alert System",
            font=("Segoe UI", 14),
            fg="#8edcff", bg="#08111f"
        ).pack()

        tk.Label(
            frame, text="● SYSTEM READY",
            font=("Segoe UI", 13, "bold"),
            fg="#62e6a8", bg="#08111f"
        ).pack(pady=25)

        init_box = tk.Frame(
            frame, bg="#10243a",
            highlightthickness=1, highlightbackground="#1e4665"
        )
        init_box.pack(fill="x", padx=100, pady=10)

        for text in [
            "✓ VOC / Gas sensing layer",
            "✓ Environmental parameters: temperature + humidity",
            "✓ Odour classification simulation",
            "✓ Voice alert subsystem"
        ]:
            tk.Label(
                init_box, text=text, anchor="w",
                font=("Segoe UI", 12), fg="#dcecff", bg="#10243a"
            ).pack(fill="x", padx=25, pady=8)

        tk.Button(
            frame, text="INITIALISE SCENTINEL",
            command=self.show_detection_menu,
            font=("Segoe UI", 14, "bold"),
            fg="white", bg="#1479b8",
            activebackground="#1c94d8",
            activeforeground="white",
            relief="flat", padx=25, pady=14,
            cursor="hand2"
        ).pack(pady=30)

    def show_detection_menu(self):
        self.clear_content()
        frame = self.content_frame()

        tk.Label(
            frame, text="SELECT SIMULATED ODOUR",
            font=("Segoe UI", 24, "bold"),
            fg="white", bg="#08111f"
        ).pack(pady=(10, 5))

        tk.Label(
            frame,
            text="Click a number to simulate the digital-nose response.",
            font=("Segoe UI", 11),
            fg="#9db3c8", bg="#08111f"
        ).pack(pady=(0, 20))

        grid = tk.Frame(frame, bg="#08111f")
        grid.pack()

        for i, odor in enumerate(self.odors.keys(), start=1):
            btn = tk.Button(
                grid,
                text=f"{i}\n{odor}",
                command=lambda o=odor: self.show_result(o),
                font=("Segoe UI", 15, "bold"),
                fg="white", bg="#123451",
                activebackground="#1b78a9",
                activeforeground="white",
                width=18, height=4,
                relief="flat", cursor="hand2"
            )
            btn.grid(row=(i-1)//2, column=(i-1)%2, padx=15, pady=12)

        tk.Button(
            frame, text="← BACK",
            command=self.show_home,
            font=("Segoe UI", 10, "bold"),
            fg="#c9d9e8", bg="#17283b",
            relief="flat", padx=18, pady=8,
            cursor="hand2"
        ).pack(pady=20)

    def show_result(self, odor):
        self.clear_content()
        frame = self.content_frame()
        d = self.odors[odor]

        tk.Label(
            frame, text="SCENT DETECTED",
            font=("Segoe UI", 28, "bold"),
            fg="#62e6a8", bg="#08111f"
        ).pack(pady=(5, 5))

        tk.Label(
            frame, text=f"Detected condition : {odor}",
            font=("Segoe UI", 18, "bold"),
            fg="white", bg="#08111f"
        ).pack(pady=5)

        progress = tk.Label(
            frame, text="● ANALYSING SENSOR PATTERN...",
            font=("Segoe UI", 11, "bold"),
            fg="#55d6ff", bg="#08111f"
        )
        progress.pack(pady=10)
        self.root.after(
            900,
            lambda: progress.winfo_exists() and
                    progress.config(text="● CLASSIFICATION COMPLETE")
        )

        card = tk.Frame(
            frame, bg="#10243a",
            highlightthickness=1, highlightbackground="#1e4665"
        )
        card.pack(fill="x", padx=80, pady=12)

        readings = [
            ("VOC", d["voc"]),
            ("MQ-2 response", d["mq2"]),
            ("MQ-135 response", d["mq135"]),
            ("Temperature", d["temperature"]),
            ("Humidity", d["humidity"]),
            ("Status", "IDENTIFIED"),
        ]

        for label, value in readings:
            row = tk.Frame(card, bg="#10243a")
            row.pack(fill="x", padx=22, pady=5)
            tk.Label(
                row, text=label, width=24, anchor="w",
                font=("Segoe UI", 11),
                fg="#9db3c8", bg="#10243a"
            ).pack(side="left")
            tk.Label(
                row, text=value, anchor="w",
                font=("Segoe UI", 11, "bold"),
                fg="white", bg="#10243a"
            ).pack(side="left")

        tk.Label(
            frame, text=f"🔊 Voice Alert: {d['voice']}",
            font=("Segoe UI", 12, "bold"),
            fg="#ffd166", bg="#08111f"
        ).pack(pady=8)

        controls = tk.Frame(frame, bg="#08111f")
        controls.pack(pady=10)

        tk.Button(
            controls, text="🔊 PLAY VOICE",
            command=lambda: self.play_voice(odor),
            font=("Segoe UI", 11, "bold"),
            fg="white", bg="#168a68",
            relief="flat", padx=20, pady=10,
            cursor="hand2"
        ).pack(side="left", padx=8)

        tk.Button(
            controls, text="TRY ANOTHER",
            command=self.show_detection_menu,
            font=("Segoe UI", 11, "bold"),
            fg="white", bg="#1479b8",
            relief="flat", padx=20, pady=10,
            cursor="hand2"
        ).pack(side="left", padx=8)

        tk.Button(
            controls, text="HOME",
            command=self.show_home,
            font=("Segoe UI", 11, "bold"),
            fg="#dcecff", bg="#17283b",
            relief="flat", padx=20, pady=10,
            cursor="hand2"
        ).pack(side="left", padx=8)

        # Automatically play the uploaded voice once.
        self.root.after(1200, lambda: self.play_voice(odor))

    def play_voice(self, odor):
        if not PYGAME_OK:
            messagebox.showerror(
                "Audio setup needed",
                "pygame is not installed.\n\n"
                "In the VS Code terminal run:\n\n"
                "python -m pip install pygame\n\n"
                "Then run simulation.py again."
            )
            return

        try:
            raw = base64.b64decode(AUDIO_DATA[odor])
            fd, filename = tempfile.mkstemp(
                prefix="scentinel_", suffix=".mp3"
            )
            os.close(fd)

            with open(filename, "wb") as f:
                f.write(raw)

            self.temp_files.append(filename)

            pygame.mixer.music.stop()
            pygame.mixer.music.load(filename)
            pygame.mixer.music.play()

        except Exception as e:
            messagebox.showerror("Audio error", str(e))

    def cleanup(self):
        try:
            if PYGAME_OK:
                pygame.mixer.music.stop()
                pygame.mixer.quit()
        except Exception:
            pass

        for filename in self.temp_files:
            try:
                os.remove(filename)
            except Exception:
                pass


if __name__ == "__main__":
    root = tk.Tk()
    app = ScentinelApp(root)
    root.protocol(
        "WM_DELETE_WINDOW",
        lambda: (app.cleanup(), root.destroy())
    )
    root.mainloop()
